#include "PbLiDiffusivityMaterial.h"

#include "PbLiPropertyHelper.h"

registerMooseObject("TMAP8App", PbLiDiffusivityMaterial);

InputParameters
PbLiDiffusivityMaterial::validParams()
{
  auto params = Material::validParams();
  params.addClassDescription(
      "Computes hydrogen-isotope diffusivity in PbLi from literature correlations and provides "
      "both regular and AD material properties.");
  params.addRequiredCoupledVar("temperature", "The PbLi temperature in K.");
  params.addParam<MaterialPropertyName>(
      "property_name", "diffusivity", "The regular material property name for the diffusivity.");
  params.addParam<MaterialPropertyName>(
      "ad_property_name", "ad_diffusivity", "The AD material property name for the diffusivity.");
  params.addParam<MooseEnum>(
      "model",
      MooseEnum("Fauvet1988 Reiter1991 Terai1992 Maeda2008 Fukada2013Classical", "Reiter1991"),
      "The PbLi diffusivity correlation.");
  params.addParam<MooseEnum>("isotope", MooseEnum("H D T", "T"), "The hydrogen isotope.");
  params.addParam<MooseEnum>(
      "reference_diffusivity_model",
      MooseEnum("Fauvet1988 Reiter1991 Terai1992 Maeda2008", "Maeda2008"),
      "Reference PbLi diffusivity model used when model=Fukada2013Classical.");
  params.addParam<MooseEnum>("reference_isotope",
                             MooseEnum("H D T", "H"),
                             "Reference isotope used when model=Fukada2013Classical.");
  params.addParam<Real>(
      "lithium_atomic_fraction", 0.17, "Lithium atomic fraction used in validity checks.");
  params.addParam<bool>(
      "silence_warnings", false, "Whether to silence out-of-range correlation warnings.");
  return params;
}

PbLiDiffusivityMaterial::PbLiDiffusivityMaterial(const InputParameters & parameters)
  : Material(parameters),
    _temperature(adCoupledValue("temperature")),
    _model(getParam<MooseEnum>("model")),
    _isotope(getParam<MooseEnum>("isotope")),
    _reference_diffusivity_model(getParam<MooseEnum>("reference_diffusivity_model")),
    _reference_isotope(getParam<MooseEnum>("reference_isotope")),
    _lithium_atomic_fraction(getParam<Real>("lithium_atomic_fraction")),
    _silence_warnings(getParam<bool>("silence_warnings")),
    _diffusivity(declareProperty<Real>(getParam<MaterialPropertyName>("property_name"))),
    _ad_diffusivity(declareADProperty<Real>(getParam<MaterialPropertyName>("ad_property_name"))),
    _issued_warning(false)
{
}

void
PbLiDiffusivityMaterial::computeQpProperties()
{
  const Real temperature = MetaPhysicL::raw_value(_temperature[_qp]);
  auto metadata = PbLiPropertyHelper::diffusivityMetadata(_model);

  if (_model == "Fukada2013Classical")
  {
    const auto reference_metadata =
        PbLiPropertyHelper::diffusivityMetadata(_reference_diffusivity_model);
    metadata.min_temperature = reference_metadata.min_temperature;
    metadata.max_temperature = reference_metadata.max_temperature;
    metadata.min_lithium_atomic_fraction = reference_metadata.min_lithium_atomic_fraction;
    metadata.max_lithium_atomic_fraction = reference_metadata.max_lithium_atomic_fraction;
    metadata.validity_note += " Reference model='" + std::string(_reference_diffusivity_model) +
                              "', reference_isotope='" + std::string(_reference_isotope) +
                              "', target isotope='" + std::string(_isotope) + "'.";
  }
  const auto warning = PbLiPropertyHelper::validityWarningMessage(
      name(), _model, temperature, _lithium_atomic_fraction, metadata);

  if (!_silence_warnings && !_issued_warning && !warning.empty())
  {
    mooseWarning(warning);
    _issued_warning = true;
  }

  const Real value = PbLiPropertyHelper::computeDiffusivity(
      _model, temperature, _isotope, &_reference_diffusivity_model, &_reference_isotope);
  _diffusivity[_qp] = value;
  _ad_diffusivity[_qp] = value;
}

