#pragma once

#include "MooseEnum.h"
#include "MooseError.h"
#include "TMAP8PhysicalConstants.h"

#include <cmath>
#include <limits>
#include <sstream>
#include <string>
#include <vector>

namespace PbLiPropertyHelper
{
const Real ideal_gas_constant = PhysicalConstants::ideal_gas_constant;

struct ModelMetadata
{
  std::string citation;
  Real min_temperature;
  Real max_temperature;
  Real min_lithium_atomic_fraction;
  Real max_lithium_atomic_fraction;
  std::string validity_note;
};

inline Real
isotopeMassNumber(const MooseEnum & isotope)
{
  if (isotope == "H")
    return 1.0;
  if (isotope == "D")
    return 2.0;
  if (isotope == "T")
    return 3.0;

  mooseError("Unsupported hydrogen isotope: ", isotope);
}

inline Real
pbliDensityKgPerM3(const Real temperature)
{
  return 10520.0 * (1.0 - 1.13e-4 * temperature);
}

inline Real
pbliMetalMolarDensity(const Real temperature, const Real lithium_atomic_fraction)
{
  constexpr Real lithium_molar_mass = 6.941e-3;
  constexpr Real lead_molar_mass = 207.2e-3;
  const Real average_atomic_molar_mass = lithium_atomic_fraction * lithium_molar_mass +
                                         (1.0 - lithium_atomic_fraction) * lead_molar_mass;

  return pbliDensityKgPerM3(temperature) / average_atomic_molar_mass;
}

inline Real
toConcentrationSolubility(const Real atomic_fraction_solubility,
                          const Real temperature,
                          const Real lithium_atomic_fraction)
{
  return atomic_fraction_solubility * pbliMetalMolarDensity(temperature, lithium_atomic_fraction);
}

inline ModelMetadata
solubilityMetadata(const MooseEnum & model)
{
  if (model == "Katsuta1985")
    return {"Katsuta et al. (1985)",
            673.15,
            773.15,
            0.157,
            0.17,
            "Hydrogen solubility in eutectic Li17Pb83."};

  if (model == "Fauvet1988")
    return {"Fauvet and Sannier (1988)",
            718.15,
            728.15,
            0.157,
            0.17,
            "Hydrogen solubility datum reported at 450 C for eutectic PbLi."};

  if (model == "Maeda2008")
    return {"Maeda et al. (2008)",
            573.15,
            773.15,
            0.157,
            0.17,
            "Hydrogen-isotope fit measured in molten Li-Pb."};

  if (model == "Reiter1991")
    return {"Reiter et al. (1991), as summarized by Mas de les Valls et al. (2008)",
            508.0,
            700.0,
            0.157,
            0.17,
            "Recommended database fit for eutectic Pb-17Li."};

  if (model == "Penalva2024")
    return {"Penalva et al. (2024)",
            514.15,
            852.15,
            0.157,
            0.157,
            "Certified Pb-15.7Li data averaged over 241-579 C."};

  if (model == "Fukada2013MixingRule")
    return {"Fukada et al. (2013)",
            -std::numeric_limits<Real>::max(),
            std::numeric_limits<Real>::max(),
            0.0,
            1.0,
            "Logarithmic mixing rule using user-supplied pure-Li and pure-Pb Sieverts constants."};

  mooseError("Unsupported PbLi solubility model: ", model);
}

inline ModelMetadata
diffusivityMetadata(const MooseEnum & model)
{
  if (model == "Fauvet1988")
    return {"Fauvet and Sannier (1988)",
            718.15,
            728.15,
            0.157,
            0.17,
            "Hydrogen diffusivity datum reported at 450 C for eutectic PbLi."};

  if (model == "Reiter1991")
    return {"Reiter et al. (1991), as summarized by Mas de les Valls et al. (2008)",
            508.0,
            700.0,
            0.157,
            0.17,
            "Recommended database fit for eutectic Pb-17Li."};

  if (model == "Terai1992")
    return {
        "Terai et al. (1992)", 573.15, 973.15, 0.157, 0.17, "Tritium diffusivity fit in Pb-17Li."};

  if (model == "Maeda2008")
    return {"Maeda et al. (2008)",
            573.15,
            773.15,
            0.157,
            0.17,
            "Hydrogen-isotope fit measured in molten Li-Pb."};

  if (model == "Fukada2013Classical")
    return {"Fukada et al. (2013)",
            -std::numeric_limits<Real>::max(),
            std::numeric_limits<Real>::max(),
            0.0,
            1.0,
            "Classical isotope-mass scaling applied to a selected reference diffusivity model."};

  mooseError("Unsupported PbLi diffusivity model: ", model);
}

inline ModelMetadata
