+  if (model == "Tanifuji1987")
+    return {"Tanifuji et al. (1987)",
+            573.0,
+            950.0,
+            "Neutron-irradiated single-crystal Li2O particles analyzed with a spherical diffusion "
+            "model."};
+
+  if (model == "Kurasawa1991")
+    return {"Kurasawa and Watanabe (1991)",
+            450.0 + 273.15,
+            820.0 + 273.15,
+            "In-situ release interpretation for single-crystal Li2O under sweep-gas chemistry "
+            "effects."};
+
+  if (model == "Tanaka1988Grain")
+    return {"Tanaka et al. (1988/1989)",
+            360.0 + 273.15,
+            600.0 + 273.15,
+            "Polycrystalline Li2O grain diffusivity from TTTEx analysis."};
+
+  if (model == "Tanaka1988GrainBoundary")
+    return {"Tanaka et al. (1988/1989)",
+            360.0 + 273.15,
+            600.0 + 273.15,
+            "Polycrystalline Li2O grain-boundary diffusivity from TTTEx analysis."};
+
+  mooseError("Unsupported Li2O diffusivity model: ", model);
+}
+
+inline ModelMetadata
+solubilityMetadata(const MooseEnum & model)
+{
+  if (model == "Ohira1989")
+    return {"O'Hira et al. (1989)",
+            -std::numeric_limits<Real>::max(),
+            std::numeric_limits<Real>::max(),
+            "Reduced-species tritium dissolution in single-crystal Li2O. The published "
+            "coefficient form has been implemented directly; the exact reported validity window "
+            "for the solubility fit still needs verification from the primary paper."};
+
+  mooseError("Unsupported Li2O solubility model: ", model);
+}
+
+inline ModelMetadata
+permeabilityMetadata(const MooseEnum & model)
+{
+  if (model == "Derived")
+    return {"Derived from the selected Li2O solubility and diffusivity models",
+            -std::numeric_limits<Real>::max(),
+            std::numeric_limits<Real>::max(),
+            "Validity is the overlap of the selected Li2O tritium solubility and diffusivity "
+            "models."};
+
+  mooseError("Unsupported Li2O permeability model: ", model);
+}
+
+inline std::string
+validityMessage(const std::string & object_name,
+                const MooseEnum & model,
+                const Real temperature,
+                const ModelMetadata & metadata)
+{
+  std::vector<std::string> violations;
+
+  if (temperature < metadata.min_temperature || temperature > metadata.max_temperature)
+  {
+    std::ostringstream oss;
+    oss << "temperature " << temperature << " K is outside [" << metadata.min_temperature << ", "
+        << metadata.max_temperature << "] K";
+    violations.push_back(oss.str());
+  }
+
+  if (violations.empty())
+    return "";
+
+  std::ostringstream oss;
+  oss << "In " << object_name << ": model '" << model
+      << "' is being used outside its documented validity range because ";
+  for (std::size_t i = 0; i < violations.size(); ++i)
+  {
+    oss << violations[i];
+    if (i + 1 < violations.size())
+      oss << " and ";
+  }
+  oss << ". " << metadata.validity_note;
+  return oss.str();
+}
+
+inline void
+handleValidity(const std::string & object_name,
+               const MooseEnum & model,
+               const Real temperature,
+               const ModelMetadata & metadata,
+               const MooseEnum & validity_action,
+               bool & issued_warning)
+{
+  const auto message = validityMessage(object_name, model, temperature, metadata);
+  if (message.empty())
+    return;
+
+  if (validity_action == "ignore")
+    return;
+
+  if (validity_action == "warning")
+  {
+    if (!issued_warning)
+    {
+      mooseWarning(message);
+      issued_warning = true;
+    }
+    return;
+  }
+
+  if (validity_action == "error")
+    mooseError(message);
+
+  mooseError("Unsupported Li2O validity_action: ", validity_action);
+}
+
+inline Real
+computeDiffusivity(const MooseEnum & model, const Real temperature)
+{
+  using std::exp;
+
+  if (model == "Ohira1989")
+    return 1.2e-7 * exp(-45.1e3 / (ideal_gas_constant * temperature)) * cm2_per_s_to_m2_per_s;
+
+  if (model == "Tanifuji1987")
+    return 0.116 * exp(-101.0e3 / (ideal_gas_constant * temperature)) * cm2_per_s_to_m2_per_s;
+
+  if (model == "Kurasawa1991")
+    return 2.0e-3 * exp(-81.7e3 / (ideal_gas_constant * temperature)) * cm2_per_s_to_m2_per_s;
+
+  if (model == "Tanaka1988Grain")
+    return 1.27e-5 * exp(-54.9e3 / (ideal_gas_constant * temperature)) * cm2_per_s_to_m2_per_s;
+
+  if (model == "Tanaka1988GrainBoundary")
+    return 1.61e2 * exp(-95.1e3 / (ideal_gas_constant * temperature)) * cm2_per_s_to_m2_per_s;
+
+  mooseError("Unsupported Li2O diffusivity model: ", model);
+}
+
+inline Real
+computeSolubility(const MooseEnum & model, const Real temperature)
+{
+  if (model == "Ohira1989")
+    return std::pow(10.0, 1290.0 / temperature + 1.14);
+
+  mooseError("Unsupported Li2O solubility model: ", model);
+}
+
+inline Real
+computePermeability(const MooseEnum & permeability_model,
+                    const MooseEnum & diffusivity_model,
+                    const MooseEnum & solubility_model,
+                    const Real temperature)
+{
+  if (permeability_model == "Derived")
+    return computeDiffusivity(diffusivity_model, temperature) *
+           computeSolubility(solubility_model, temperature);
+
+  mooseError("Unsupported Li2O permeability model: ", permeability_model);
+}
+}
