registerMooseObject("TMAP8App", TritiumPermeabilityLi2O);

InputParameters
TritiumPermeabilityLi2O::validParams()
{
  auto params = Material::validParams();
  params.addClassDescription(
      "Computes tritium permeability in Li2O from internally selected Li2O diffusivity and "
      "solubility models, and provides both regular and AD material properties.");
  params.addRequiredCoupledVar("temperature", "The Li2O temperature in K.");
  params.addParam<MaterialPropertyName>(
      "property_name", "permeability", "The regular material property name for the permeability.");
  params.addParam<MaterialPropertyName>(
      "ad_property_name", "ad_permeability", "The AD material property name for the permeability.");
  params.addParam<MooseEnum>(
      "model", MooseEnum("Derived", "Derived"), "The Li2O tritium permeability correlation.");
  params.addParam<MooseEnum>("diffusivity_model",
                             MooseEnum("Ohira1989 Tanifuji1987 Kurasawa1991 Tanaka1988Grain "
                                       "Tanaka1988GrainBoundary",
                                       "Tanifuji1987"),
                             "The Li2O tritium diffusivity correlation used when model=Derived.");
  params.addParam<MooseEnum>("solubility_model", MooseEnum("Ohira1989", "Ohira1989"),
                             "The Li2O tritium solubility correlation used when model=Derived.");
  params.addParam<MooseEnum>("validity_action",
                             MooseEnum("ignore warning error", "warning"),
                             "How the material responds when the selected model is used outside "
                             "its documented validity range.");
  return params;
}

TritiumPermeabilityLi2O::TritiumPermeabilityLi2O(const InputParameters & parameters)
  : Material(parameters),
    _temperature(adCoupledValue("temperature")),
    _model(getParam<MooseEnum>("model")),
    _diffusivity_model(getParam<MooseEnum>("diffusivity_model")),
    _solubility_model(getParam<MooseEnum>("solubility_model")),
    _validity_action(getParam<MooseEnum>("validity_action")),
    _permeability(declareProperty<Real>(getParam<MaterialPropertyName>("property_name"))),
    _ad_permeability(declareADProperty<Real>(getParam<MaterialPropertyName>("ad_property_name"))),
    _issued_warning(false)
{
}

void
TritiumPermeabilityLi2O::computeQpProperties()
{
  const Real temperature = MetaPhysicL::raw_value(_temperature[_qp]);
  auto metadata = Li2OPropertyHelper::permeabilityMetadata(_model);

  if (_model == "Derived")
  {
    const auto diffusivity_metadata = Li2OPropertyHelper::diffusivityMetadata(_diffusivity_model);
    const auto solubility_metadata = Li2OPropertyHelper::solubilityMetadata(_solubility_model);
    metadata.min_temperature =
        std::max(diffusivity_metadata.min_temperature, solubility_metadata.min_temperature);
    metadata.max_temperature =
        std::min(diffusivity_metadata.max_temperature, solubility_metadata.max_temperature);
    metadata.validity_note += " Selected diffusivity model='" +
                              std::string(_diffusivity_model) + "', solubility model='" +
                              std::string(_solubility_model) + "'.";
  }

  Li2OPropertyHelper::handleValidity(
      name(), _model, temperature, metadata, _validity_action, _issued_warning);

  const Real value = Li2OPropertyHelper::computePermeability(
      _model, _diffusivity_model, _solubility_model, temperature);
  _permeability[_qp] = value;
  _ad_permeability[_qp] = value;
}

